PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?paternalGrandmother ?paternalGrandmotherLabel WHERE {
  dbr:John_III,_Duke_of_Cleves dbp:father ?father .
  ?father dbp:mother ?paternalGrandmother .
  OPTIONAL { ?paternalGrandmother rdfs:label ?paternalGrandmotherLabel .
             FILTER (lang(?paternalGrandmotherLabel) = "en") }
}
LIMIT 100

